-- Import all 48 PDF summaries as PRIVATE saved drafts. No details are invented.
-- Run in the development project's SQL Editor after creating your app account.
-- For safety this requires exactly one auth account. If there are multiple,
-- do not delete accounts: supply the intended account ID in a tailored script instead.
begin;
-- Personal recipe drafts preserve missing values and restrict catalog visibility.
alter table public.recipes add column if not exists owner_id uuid references auth.users(id) on delete cascade;
alter table public.recipes add column if not exists category text check (category in ('breakfast', 'lunch', 'dinner', 'side'));
alter table public.recipes add column if not exists incomplete boolean not null default false;
alter table public.recipes alter column minutes drop not null;
alter table public.recipes alter column servings drop not null;
alter table public.recipes alter column difficulty drop not null;
drop policy if exists catalog_read on public.recipes;
create policy catalog_read on public.recipes for select to anon, authenticated
using (owner_id is null or (select auth.uid()) = owner_id);

drop policy if exists saves_insert on public.saved_recipes;
create policy saves_insert on public.saved_recipes for insert to authenticated
with check ((select auth.uid()) = user_id and exists (
  select 1 from public.recipes where id = recipe_id
));

do $import$
declare
  target_user uuid;
  account_count integer;
  source_rows jsonb := $recipes$[{"entry": 31, "title": "Healthy Banana Pancakes", "description": "One-person recipe; banana, egg, rolled oats or almond flour; no baking powder.", "category": "breakfast", "page": 2}, {"entry": 32, "title": "Banana Coconut Chia Pudding", "description": "Banana, coconut milk, chia seeds, Medjool date, vanilla, Greek yogurt and toppings; thickening and sweetening discussed.", "category": "breakfast", "page": 2}, {"entry": 33, "title": "Banana Bread Chia Pudding", "description": "Separate banana bread-inspired variation; exact preferred version not recovered.", "category": "breakfast", "page": 2}, {"entry": 34, "title": "Greek Yogurt Bowls with Fruit and Granola", "description": "Title only.", "category": "breakfast", "page": 2}, {"entry": 35, "title": "Eggs, Sausage, Cheese and Avocado Bagels", "description": "Title only.", "category": "breakfast", "page": 2}, {"entry": 36, "title": "Cottage Cheese Fruit Bowls", "description": "Title only.", "category": "breakfast", "page": 2}, {"entry": 38, "title": "Healthy Banana Sweet Treats", "description": "Title only; snack/dessert rather than a confirmed breakfast recipe. Placed here to retain the requested four categories.", "category": "breakfast", "page": 2}, {"entry": 4, "title": "Buffalo Chicken Wraps", "description": "Chicken tenders, shredded lettuce, pickles, tortilla and creamy spicy sauce; planned with sweet potatoes.", "category": "lunch", "page": 1}, {"entry": 7, "title": "Pepperoncini Chicken Salad", "description": "Greek yogurt, dill and red onion.", "category": "lunch", "page": 1}, {"entry": 10, "title": "Chicken Avocado Crunch Salad", "description": "Title only.", "category": "lunch", "page": 1}, {"entry": 11, "title": "Chicken Caprese Bowls", "description": "Title only.", "category": "lunch", "page": 1}, {"entry": 12, "title": "Pesto Chicken Burrata Sourdough Toast", "description": "Title only.", "category": "lunch", "page": 1}, {"entry": 30, "title": "Bean and Cheese Burritos", "description": "Refried black beans, onion, salsa, shredded cheese and tortillas.", "category": "lunch", "page": 2}, {"entry": 37, "title": "Turkey Avocado Bagel Sandwich", "description": "Title only.", "category": "lunch", "page": 2}, {"entry": 1, "title": "Crispy Garlic Parmesan Chicken Tenders", "description": "Breaded chicken tenderloins, Parmesan, panko, garlic, paprika and Italian seasoning. Source suggests air frying around 390 F for 9-12 minutes and cooking to 165 F; served with broccoli, sweet potato and dipping sauce.", "category": "dinner", "page": 1}, {"entry": 2, "title": "Honey Dijon Chicken", "description": "Honey, Dijon mustard, garlic and seasonings; paired with crispy sweet potatoes and Brussels sprouts.", "category": "dinner", "page": 1}, {"entry": 3, "title": "Sweet and Spicy Chicken Thighs", "description": "Sweet heat marinated boneless thighs; air fried with sweet potato and shaved Brussels sprouts.", "category": "dinner", "page": 1}, {"entry": 5, "title": "Garlic Parmesan Chicken Tenders, unbreaded version", "description": "Separate unbreaded variation.", "category": "dinner", "page": 1}, {"entry": 6, "title": "Pesto Pasta with Grilled Chicken", "description": "Title only.", "category": "dinner", "page": 1}, {"entry": 8, "title": "Creamy High Protein Chicken Mac and Cheese", "description": "Title only; possible overlap with entry 25, retained separately.", "category": "dinner", "page": 1}, {"entry": 9, "title": "Gochujang Sesame Chicken Noodle Bowls", "description": "Title only.", "category": "dinner", "page": 1}, {"entry": 13, "title": "Honey Garlic or Sweet Heat Chicken with Rice", "description": "Title contains alternative flavors; no exact version supplied.", "category": "dinner", "page": 1}, {"entry": 14, "title": "Chicken Broccoli and Ziti", "description": "Title only.", "category": "dinner", "page": 1}, {"entry": 15, "title": "Pepperoncini Chicken", "description": "Title only.", "category": "dinner", "page": 1}, {"entry": 16, "title": "Sesame Ginger Stir Fry Chicken", "description": "Title only.", "category": "dinner", "page": 1}, {"entry": 17, "title": "Spicy Butternut Squash Pasta with Chicken", "description": "Roasted butternut squash, rigatoni, garlic, Parmesan, chili and chicken. Originally planned with burrata and sage; later made without sage.", "category": "dinner", "page": 1}, {"entry": 18, "title": "Creamy Spicy Mini Meatball Pasta", "description": "Mini ground beef meatballs, spaghetti, tomato paste, garlic, yellow onion, Calabrian chili peppers, Parmesan and bone broth.", "category": "dinner", "page": 1}, {"entry": 19, "title": "Creamy Garlic Parmesan Chicken Sausage Spaghetti", "description": "Italian chicken sausage, garlic, shallot, spaghetti, bone broth, Greek yogurt, Parmesan and chili flakes.", "category": "dinner", "page": 1}, {"entry": 20, "title": "Creamy Tomato Garlic Chicken Angel Hair", "description": "Chicken, cherry tomatoes, shallot, garlic, tomato paste, bone broth, heavy cream, butter and Parmesan.", "category": "dinner", "page": 1}, {"entry": 21, "title": "Creamy Spicy Tomato Chicken Sausage Orzo", "description": "Chicken sausage, orzo, tomatoes, garlic, chili and Parmesan; originally suggested with spinach.", "category": "dinner", "page": 2}, {"entry": 22, "title": "Creamy Pepperoncini Chicken Sausage Pasta", "description": "Title only.", "category": "dinner", "page": 2}, {"entry": 23, "title": "Burrata Chicken Pasta", "description": "Title only.", "category": "dinner", "page": 2}, {"entry": 24, "title": "Homemade Hamburger Helper", "description": "Title only.", "category": "dinner", "page": 2}, {"entry": 25, "title": "High Protein Mac and Cheese with Chicken", "description": "Title only; possible overlap with entry 8, retained separately.", "category": "dinner", "page": 2}, {"entry": 26, "title": "Spicy Calabrian Chili Pasta", "description": "Title only.", "category": "dinner", "page": 2}, {"entry": 27, "title": "Ground Beef Taco Bowls", "description": "Beef, rice, avocado, cheese, tomatoes and taco toppings.", "category": "dinner", "page": 2}, {"entry": 28, "title": "Loaded Taco Sweet Potatoes", "description": "Roasted sweet potato stuffed with seasoned beef and toppings.", "category": "dinner", "page": 2}, {"entry": 29, "title": "Steak Rice Bowls", "description": "Steak, rice, cucumber, avocado, pickled onions and dressing.", "category": "dinner", "page": 2}, {"entry": 39, "title": "Roasted Sweet Potato Halves", "description": "Olive oil and garlic salt; roast cut side down.", "category": "side", "page": 2}, {"entry": 40, "title": "Air Fryer Sweet Potato Cubes", "description": "Seasoned crispy cubes.", "category": "side", "page": 2}, {"entry": 41, "title": "Homemade Pico de Gallo", "description": "Tomato, red onion, jalapeno, cilantro and lime.", "category": "side", "page": 2}, {"entry": 42, "title": "Healthy Chicken Dipping Sauce", "description": "Greek yogurt-based sauce for breaded chicken.", "category": "side", "page": 2}, {"entry": 43, "title": "Crispy Roasted Brussels Sprouts", "description": "Title only.", "category": "side", "page": 2}, {"entry": 44, "title": "Garlic Roasted Broccoli", "description": "Title only.", "category": "side", "page": 2}, {"entry": 45, "title": "Roasted Butternut Squash", "description": "Title only.", "category": "side", "page": 2}, {"entry": 46, "title": "Honey Dijon Dressing", "description": "Title only.", "category": "side", "page": 2}, {"entry": 47, "title": "Creamy Pepperoncini Yogurt Dressing", "description": "Title only.", "category": "side", "page": 2}, {"entry": 48, "title": "Homemade Sweet and Spicy Chicken Sauce", "description": "Title only.", "category": "side", "page": 2}]$recipes$::jsonb;
begin
  select count(*) into account_count from auth.users;
  if account_count <> 1 then
    raise exception 'Expected exactly one app account, found %. Create your account first, or request an account-specific import if multiple accounts exist.', account_count;
  end if;
  select id into target_user from auth.users;
  insert into public.recipes (id,owner_id,title,description,cuisine,minutes,servings,difficulty,category,incomplete,ingredients,instructions,provenance)
  select md5(target_user::text || ':personal-pdf:' || x.entry::text)::uuid,
    target_user,x.title,x.description,'Not recorded',null,null,null,x.category,true,'[]'::jsonb,'[]'::jsonb,
    jsonb_build_object('source','Your ChatGPT recipe collection','url',null,
      'permission','Personal recipe summary; full details not recovered.',
      'method','generated','document','My_Recipe_Collection_2025_2026_9267.pdf','entry',x.entry,'page',x.page)
  from jsonb_to_recordset(source_rows) as x(entry integer,title text,description text,category text,page integer)
  on conflict (id) do nothing;
  insert into public.saved_recipes (user_id,recipe_id)
  select target_user, md5(target_user::text || ':personal-pdf:' || x.entry::text)::uuid
  from jsonb_to_recordset(source_rows) as x(entry integer)
  on conflict (user_id,recipe_id) do nothing;
end;
$import$;
notify pgrst, 'reload schema';
commit;
select count(*) as personal_recipe_drafts from public.recipes
where owner_id = (select id from auth.users) and incomplete;
